        elif char.isdigit() or (char == '-' and s[index + 1].isdigit()):
            return parse_number()
        elif s.startswith('true', index):
            index += 4
            return True
        elif s.startswith('false', index):
            index += 5
            return False
        elif s.startswith('null', index):
            index += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Invalid JSON input at index {index}")

    def parse_string():
        nonlocal index
        start_index = index + 1
        index += 1
        while index < length:
            char = s[index]
            if char == '"':
                break
            elif char == '\\':
                index += 2  # Skip the escape character and the next character
            else:
                index += 1
        else:
            raise ValueError("Unterminated string")
        result = s[start_index:index]
        index += 1  # Skip closing quote
        return result.replace('\\"', '"').replace('\\b', '\b').replace('\\f', '\f').replace('\\n', '\n').replace('\\r', '\r').replace('\\t', '\t')

    def parse_number():
