    """

    index = 0
    length = len(s)
    stack = []
    current_value = None
    mode = None  # Modes: "object", "array", "key"
    key = ""

    def next_token():
        nonlocal index
        while index < length and s[index].isspace():
            index += 1
        if index >= length:
            return None
        token = s[index]
        index += 1
        return token

