    """
    A token-based parser that uses a buffer to extract tokens and build JSON objects iteratively
    by maintaining a global state for parsing values, objects, and arrays. It constructs
    the nested structure through a manually managed context stack.
    """

    index = 0
    length = len(s)
    tokens = []

    def tokenize():
        nonlocal index
        while index < length:
            char = s[index]
            if char.isspace():
                index += 1
                continue
            if char == '"':
                start = index
                index += 1
                while index < length and s[index] != '"':
                    if s[index] == '\\':
                        index += 2
                    else:
                        index += 1
                tokens.append(s[start:index + 1])
                index += 1
                continue
            if char in '-0123456789':
                start = index
                if char == '-':
                    index += 1
                while index < length and s[index] in '0123456789':
                    index += 1
                if index < length and s[index] == '.':
                    index += 1
                    while index < length and s[index] in '0123456789':
                        index += 1
                if index < length and s[index] in 'eE':
                    index += 1
                    if index < length and s[index] in '+-':
                        index += 1
                    while index < length and s[index] in '0123456789':
                        index += 1
                tokens.append(s[start:index])
                continue
            if s.startswith('true', index):
                tokens.append('true')
                index += 4
                continue
            if s.startswith('false', index):
                tokens.append('false')
                index += 5
                continue
            if s.startswith('null', index):
                tokens.append('null')
                index += 4
                continue
            if char in '{}[],':
                tokens.append(char)
                index += 1
                continue
            raise ValueError(f"Unexpected character: {char}")

    def parse_value():
        token = tokens.pop(0)
        if token == '"':
            return token[1:-1].encode().decode('unicode_escape')
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            return int(token) if '.' not in token else float(token)
        if token == 'true':
            return True
        if token == 'false':
            return False
        if token == 'null':
            return None
        if token == '[':
            return parse_array()
        if token == '{':
            return parse_object()
        raise ValueError(f"Invalid token: {token}")

    def parse_array():
        array = []
        while tokens:
            if tokens[0] == ']':
                tokens.pop(0)
                return array
            array.append(parse_value())
            if tokens[0] == ',':
                tokens.pop(0)
            elif tokens[0] == ']':
                tokens.pop(0)
                return array
            else:
                raise ValueError("Expected ',' or ']' in array")

    def parse_object():
        obj = {}
        while tokens:
            if tokens[0] == '}':
                tokens.pop(0)
                return obj
            key = parse_value()  # Expecting a string token
            if tokens.pop(0) != ':':
                raise ValueError("Expected ':' in object")
            value = parse_value()
            obj[key] = value
            if tokens[0] == ',':
                tokens.pop(0)
            elif tokens[0] == '}':
                tokens.pop(0)
                return obj
            else:
                raise ValueError("Expected ',' or '}' in object")

    tokenize()
    return parse_value()
